const s = $('Stats Settings').first().json;
const lookback = Number(s.lookback_days) || 30;
const cutoff = DateTime.now().setZone('Asia/Kolkata').minus({ days: lookback });
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  if (String(r.Review_Status || '') !== 'Published') continue;
  if (String(r.Destination || '').toLowerCase() !== 'company') continue;
  const urn = String(r.LinkedIn_URN || '').trim();
  if (!urn.startsWith('urn:li:')) continue;
  const published = DateTime.fromFormat(String(r.Published_At || ''), 'yyyy-MM-dd HH:mm', { zone: 'Asia/Kolkata' });
  if (!published.isValid || published < cutoff) continue;
  out.push({ json: Object.assign({}, r, {
    org_urn: s.company_org_urn,
    api_version: s.linkedin_api_version,
    urn_param: urn.includes(':ugcPost:') ? 'ugcPosts' : 'shares'
  }) });
}
return out;

const post = $('Pick Company Posts').item.json;
const now = DateTime.now().setZone('Asia/Kolkata').toFormat('yyyy-MM-dd HH:mm');
const el = Array.isArray($json.elements) ? $json.elements[0] : null;
const st = el && el.totalShareStatistics ? el.totalShareStatistics : null;
if (!st) {
  const err = $json.error ? ($json.error.message || JSON.stringify($json.error)) : 'No statistics returned';
  return { json: {
    row_number: post.row_number,
    Impressions: post.Impressions, Unique_Impressions: post.Unique_Impressions, Reactions: post.Reactions,
    Comments: post.Comments, Reposts: post.Reposts, Clicks: post.Clicks, Engagement_Rate: post.Engagement_Rate,
    Stats_Updated_At: post.Stats_Updated_At || '',
    Stats_Source: ('Error ' + now + ': ' + String(err)).slice(0, 300)
  } };
}
const imp = Number(st.impressionCount) || 0;
const reactions = Number(st.likeCount) || 0;
const comments = Number(st.commentCount) || 0;
const reposts = Number(st.shareCount) || 0;
const clicks = Number(st.clickCount) || 0;
const rate = imp > 0 ? ((reactions + comments + reposts + clicks) / imp * 100) : 0;
return { json: {
  row_number: post.row_number,
  Impressions: imp,
  Unique_Impressions: Number(st.uniqueImpressionsCount) || 0,
  Reactions: reactions,
  Comments: comments,
  Reposts: reposts,
  Clicks: clicks,
  Engagement_Rate: rate.toFixed(2) + '%',
  Stats_Updated_At: now,
  Stats_Source: 'LinkedIn API'
} };

let p = null;
try { p = $('Last Week').first().json; } catch (e) { p = null; }
if (!p || !p.period_start) {
  try { p = $('Last Month').first().json; } catch (e) { p = null; }
}
if (!p || !p.period_start) throw new Error('Report period missing');
const NL = String.fromCharCode(10);
const Z = 'Asia/Kolkata';
const start = DateTime.fromISO(p.period_start, { zone: Z });
const end = DateTime.fromISO(p.period_end, { zone: Z });
const prevStart = DateTime.fromISO(p.prev_start, { zone: Z });
const num = v => { const n = Number(String(v === undefined || v === null ? '' : v).replace(/[^0-9.]/g, '')); return isNaN(n) ? 0 : n; };
const rows = $input.all().map(i => i.json).filter(r => Object.keys(r).length > 0 && String(r.Review_Status || '') === 'Published');
const posts = [];
for (const r of rows) {
  const at = DateTime.fromFormat(String(r.Published_At || ''), 'yyyy-MM-dd HH:mm', { zone: Z });
  if (!at.isValid) continue;
  const imp = num(r.Impressions);
  const eng = num(r.Reactions) + num(r.Comments) + num(r.Reposts) + num(r.Clicks);
  posts.push({ r, at, imp, eng, hasStats: imp > 0, er: imp > 0 ? eng / imp * 100 : 0, predicted: num(r.Avg_Predicted_Score) });
}
const cur = posts.filter(x => x.at >= start && x.at < end);
const prev = posts.filter(x => x.at >= prevStart && x.at < start);
const sum = (arr, f) => arr.reduce((a, x) => a + f(x), 0);
const totals = arr => {
  const withStats = arr.filter(x => x.hasStats);
  const imp = sum(withStats, x => x.imp);
  const eng = sum(withStats, x => x.eng);
  return { count: arr.length, withStats: withStats.length, imp, eng, er: imp > 0 ? eng / imp * 100 : 0,
    reactions: sum(withStats, x => num(x.r.Reactions)), comments: sum(withStats, x => num(x.r.Comments)),
    reposts: sum(withStats, x => num(x.r.Reposts)), clicks: sum(withStats, x => num(x.r.Clicks)) };
};
const pct = (a, b) => b > 0 ? ((a - b) / b * 100 >= 0 ? '+' : '') + ((a - b) / b * 100).toFixed(0) + '%' : 'n/a';
const T = totals(cur);
const P = totals(prev);
let weekdays = 0;
for (let d = start; d < end; d = d.plus({ days: 1 })) { if (d.weekday <= 5) weekdays++; }
const planned = weekdays * 2;
const lines = [];
lines.push('LinkedIn ' + p.report_type + ' Performance Report');
lines.push(p.label);
lines.push('');
if (cur.length === 0) {
  lines.push('No posts were published in this period (planned slots: ' + planned + ').');
} else {
  const personal = cur.filter(x => String(x.r.Destination).toLowerCase() === 'personal');
  const company = cur.filter(x => String(x.r.Destination).toLowerCase() === 'company');
  lines.push('Published: ' + cur.length + ' of ' + planned + ' planned slots (Personal ' + personal.length + ', Company ' + company.length + ')');
  lines.push('Posts with stats: ' + T.withStats + ' of ' + T.count);
  lines.push('');
  lines.push('Impressions: ' + T.imp.toLocaleString('en-IN') + ' (' + pct(T.imp, P.imp) + ' vs previous period)');
  lines.push('Reactions ' + T.reactions + ' | Comments ' + T.comments + ' | Reposts ' + T.reposts + ' | Clicks ' + T.clicks);
  lines.push('Engagement rate: ' + T.er.toFixed(2) + '% (previous ' + (P.withStats ? P.er.toFixed(2) + '%' : 'n/a') + ')');
  for (const [name, arr] of [['Personal', personal], ['Company', company]]) {
    const t = totals(arr);
    if (arr.length) lines.push('  ' + name + ': ' + t.imp.toLocaleString('en-IN') + ' impressions, ' + t.er.toFixed(2) + '% engagement');
  }
  const ranked = cur.filter(x => x.hasStats).sort((a, b) => b.er - a.er);
  if (ranked.length) {
    lines.push('');
    lines.push('Top posts by engagement:');
    ranked.slice(0, 3).forEach((x, i) => lines.push((i + 1) + '. ' + String(x.r.Topic || x.r.Content_ID).slice(0, 60) + ' (' + x.r.Destination + ') - ' + x.er.toFixed(2) + '%, ' + x.imp + ' impressions'));
    if (ranked.length > 3) {
      const w = ranked[ranked.length - 1];
      lines.push('Lowest: ' + String(w.r.Topic || w.r.Content_ID).slice(0, 60) + ' - ' + w.er.toFixed(2) + '%');
    }
    const group = key => {
      const m = {};
      for (const x of ranked) { const k = String(x.r[key] || 'Unspecified'); (m[k] = m[k] || []).push(x); }
      return Object.keys(m).map(k => { const t = totals(m[k]); return k + ' ' + t.er.toFixed(1) + '% (' + m[k].length + ')'; }).join(', ');
    };
    lines.push('');
    lines.push('By pillar: ' + group('Pillar'));
    lines.push('By language: ' + group('Language'));
    const hi = ranked.filter(x => x.predicted >= 80);
    const lo = ranked.filter(x => x.predicted > 0 && x.predicted < 80);
    if (hi.length && lo.length) {
      lines.push('AI score check: posts scored 80+ got ' + totals(hi).er.toFixed(2) + '% vs ' + totals(lo).er.toFixed(2) + '% for the rest');
    }
  }
  const missing = cur.filter(x => !x.hasStats);
  if (missing.length) {
    lines.push('');
    lines.push('Missing stats (' + missing.length + '): ' + missing.map(x => x.r.Content_ID).join(', '));
    lines.push('Personal profile stats are not available through the API - copy impressions, reactions, comments and reposts from LinkedIn into the sheet.');
  }
}
return [{ json: { report: lines.join(NL), report_type: p.report_type, posts_in_period: cur.length } }];
